-- MP-0056: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='dap' and type='party') then raise exception 'MP-0056: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('mordi-bimol','kelvin-yii-lee-wuen','chong-chieng-jen') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0056: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('mas gading','bandar kuching','stampin') and slug not in ('mordi-bimol','kelvin-yii-lee-wuen','chong-chieng-jen')) then raise exception 'MP-0056: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0056:%' and (m.source_type <> 'editorial' or e.slug not in ('mordi-bimol','kelvin-yii-lee-wuen','chong-chieng-jen') or m.import_key not like 'MP-0056:' || e.slug || ':%')) then raise exception 'MP-0056: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'mordi-bimol','Mordi Bimol','government','Deputy Minister of Youth and Sports','Mas Gading','Sarawak','Mordi Bimol represents Mas Gading, Sarawak, in the Dewan Rakyat. Current role: Deputy Minister of Youth and Sports. Affiliated with DAP.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4231','/portraits/mordi-bimol.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P192.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4231"}, {"label": "DAP · current Sarawak representatives", "url": "https://dapmalaysia.org/sarawak-representatives/"}]'::jsonb from public.entities parent where parent.slug='dap' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'kelvin-yii-lee-wuen','Kelvin Yii Lee Wuen','government','Member of the Dewan Rakyat','Bandar Kuching','Sarawak','Kelvin Yii Lee Wuen represents Bandar Kuching, Sarawak, in the Dewan Rakyat. Affiliated with DAP.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4234','/portraits/kelvin-yii-lee-wuen.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P195.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4234"}, {"label": "DAP · current Sarawak representatives", "url": "https://dapmalaysia.org/sarawak-representatives/"}]'::jsonb from public.entities parent where parent.slug='dap' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'chong-chieng-jen','Chong Chieng Jen','government','Member of the Dewan Rakyat','Stampin','Sarawak','Chong Chieng Jen represents Stampin, Sarawak, in the Dewan Rakyat. Affiliated with DAP.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4235','/portraits/chong-chieng-jen.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P196.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4235"}, {"label": "DAP · current Sarawak representatives", "url": "https://dapmalaysia.org/sarawak-representatives/"}]'::jsonb from public.entities parent where parent.slug='dap' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('mordi-bimol','kelvin-yii-lee-wuen','chong-chieng-jen') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0056: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0056:mordi-bimol:youth-budget-consultation-tour','Complete six youth-budget consultation stops','Governance','in_progress',50,null,null,null,'2026-09-19','https://www.bernama.com/radio/news.php?id=2609302','Mordi reported three of six Jelajah Kita Dengar consultation stops completed, with Sabah, the Southern Zone and Sarawak still scheduled.','Progress is 3 completed stops / 6 planned stops = 50%, as reported on 19 September. This is a historical event-count snapshot. The remaining stops and delivery of a memorandum to the Prime Minister were not verified; their scheduled dates do not prove completion.','2026-11-10','editorial',false from public.entities e where e.slug='mordi-bimol' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0056:kelvin-yii-lee-wuen:sgh-equipment-allocation','Provide RM100,000 for Sarawak General Hospital equipment and facilities','Health','achieved',null,null,null,null,'2026-01-27','https://en.dapsarawak.org/rm100000-allocation-by-bandar-kuching-mp-boosts-equipment-and-facility-upgrades-at-sarawak-general-hospital/','Kelvin’s office reported handing over the allocation for computers, seating and other essential hospital equipment.','The dated party report establishes the funding handover, not completed procurement, installed equipment or measured clinical improvements. The exact earlier handover day is not specified.','2026-11-10','editorial',false from public.entities e where e.slug='kelvin-yii-lee-wuen' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,exclud